#include <cstdio>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <iomanip>
#include <cmath>
#include <string>

static uint32_t bits32(float f){ uint32_t u; memcpy(&u,&f,4); return u; }
static uint64_t bits64(double d){ uint64_t u; memcpy(&u,&d,8); return u; }

// print exact decimal expansion of a float/double using long double-free approach:
// use printf %.*f with enough digits (glibc is exact for binary->decimal)
static void exact32(const char* name, float f){
    printf("EX32 %-28s bits=0x%08x  %.17g  exact=%.60f\n", name, bits32(f), (double)f, (double)f);
}
static void exact64(const char* name, double d){
    printf("EX64 %-28s bits=0x%016llx  %.17g  exact=%.60f\n", name, (unsigned long long)bits64(d), d, d);
}

int main(){
    float a = 0.33f, b = 0.66f;
    // line1 path
    float p60 = static_cast<float>(60)/static_cast<float>(200);
    // line3 path
    float p13 = static_cast<float>(1)/static_cast<float>(3);

    puts("=== EXACT BINARY VALUES ===");
    exact32("0.33f", a);
    exact32("0.66f", b);
    exact32("60f/200f", p60);
    exact32("1f/3f", p13);

    puts("--- f32 multiply by 100 ---");
    float a100f = a * 100.0f;
    float b100f = b * 100.0f;
    float p60_100f = p60 * 100.0f;
    float p13_100f = p13 * 100.0f;
    exact32("0.33f*100f", a100f);
    exact32("0.66f*100f", b100f);
    exact32("(60f/200f)*100f", p60_100f);
    exact32("(1f/3f)*100f", p13_100f);

    puts("--- widen then f64 multiply ---");
    double a100d = (double)a * 100.0;
    double b100d = (double)b * 100.0;
    double p60_100d = (double)p60 * 100.0;
    double p13_100d = (double)p13 * 100.0;
    exact64("(double)0.33f*100", a100d);
    exact64("(double)0.66f*100", b100d);
    exact64("(double)(60f/200f)*100", p60_100d);
    exact64("(double)(1f/3f)*100", p13_100d);

    puts("--- f64 divide then multiply (pure double path) ---");
    double d60 = 60.0/200.0*100.0;
    double d13 = 1.0/3.0*100.0;
    exact64("60.0/200.0*100", d60);
    exact64("1.0/3.0*100", d13);

    puts("--- f32 mul widened to f64 (what ostream<<float does) ---");
    exact64("(double)(0.33f*100f)", (double)a100f);
    exact64("(double)(0.66f*100f)", (double)b100f);
    exact64("(double)((60f/200f)*100f)", (double)p60_100f);
    exact64("(double)((1f/3f)*100f)", (double)p13_100f);

    puts("");
    puts("=== ULP / SPACING near 33 and 30 and 66 ===");
    printf("SPACING nextafter(33.0f) - 33.0f      = %.17g  (2^-18=%.17g)\n",
        (double)std::nextafterf(33.0f,1e9f)-33.0, (double)ldexp(1.0,-18));
