pub fn pct(v: f32, prec: usize) -> String { format!("{:.*}%", prec, (v * 100.0f32) as f64) }
pub fn ratio(p: u64, t: u64) -> String { format!("{}/{}", p, t) }
pub fn frac(p: u64, t: u64) -> f32 { p as f32 / t as f32 }
