fn main(){
  let vals: [f32;6]=[33.0, 66.0, 30.000002, 33.333336, 0.33*100.0, 1.0f32/3.0*100.0];
  for v in vals { 
    for p in 0..4usize {
      let a=format!("{:.*}",p,v); let b=format!("{:.*}",p,v as f64);
      println!("{:>12} p={} f32=\"{}\" f64=\"{}\" {}",v,p,a,b, if a==b {"SAME"} else {"DIFFER"});
    }
  }
  // exhaustive-ish: every f32 bit pattern in a band, f32-direct vs widened
  let mut diff=0u64; let mut n=0u64;
  for b in 0x41f00000u32..0x42900000u32 {
    let f=f32::from_bits(b);
    for p in 0..3usize { if format!("{:.*}",p,f)!=format!("{:.*}",p,f as f64) {diff+=1;} n+=1; }
  }
  println!("EXHAUSTIVE band [30,72]: {} f32-direct vs widened comparisons, {} differ", n, diff);
}
EOF
